create or replace function public.srk_process_booking_matching_queue()
returns integer language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare
  v_queue record; v_booking public.service_bookings%rowtype; v_timeout integer;
  v_tech_count integer; v_helper_count integer; v_tech_offered integer; v_helper_offered integer;
  v_candidate record; v_level uuid; v_rate_id uuid; v_rate numeric(10,2); v_role text;
  v_inserted integer:=0; v_offered boolean;
begin
  select nullif(setting_value::text,'null')::integer into v_timeout
  from public.srk_system_settings where setting_key='offer_timeout_seconds';

  if v_timeout is not null then
    update public.srk_booking_workers set assignment_status='rejected',rejected_at=clock_timestamp(),
      admin_note='Offer timed out',updated_at=clock_timestamp()
    where assignment_status='offered' and offer_expires_at is not null and offer_expires_at<=clock_timestamp();
  end if;

  for v_queue in
    select q.* from public.srk_booking_matching_queue q
    where q.queue_status in ('pending','searching','waiting') and q.next_attempt_at<=clock_timestamp()
    order by q.created_at for update skip locked limit 25
  loop
    select * into v_booking from public.service_bookings where id=v_queue.booking_id for update;
    if not found or v_booking.status='cancelled' then
      update public.srk_booking_matching_queue set queue_status='cancelled',updated_at=clock_timestamp()
      where booking_id=v_queue.booking_id;
      continue;
    end if;

    select count(*) into v_tech_count from public.srk_booking_workers
      where booking_id=v_booking.id and worker_role='technician'
        and assignment_status in ('accepted','assigned','working','paused','completed');
    select count(*) into v_helper_count from public.srk_booking_workers
      where booking_id=v_booking.id and worker_role='helper'
        and assignment_status in ('accepted','assigned','working','paused','completed');
    select count(*) into v_tech_offered from public.srk_booking_workers
      where booking_id=v_booking.id and worker_role='technician' and assignment_status='offered';
    select count(*) into v_helper_offered from public.srk_booking_workers
      where booking_id=v_booking.id and worker_role='helper' and assignment_status='offered';

    if v_tech_count>=v_booking.requested_technician_count and v_helper_count>=v_booking.requested_helper_count then
      update public.srk_booking_workers set assignment_status='assigned',updated_at=clock_timestamp()
        where booking_id=v_booking.id and assignment_status='accepted';
      update public.srk_booking_matching_queue set queue_status='fulfilled',
        completed_at=coalesce(completed_at,clock_timestamp()),updated_at=clock_timestamp()
        where booking_id=v_booking.id;
      update public.service_bookings set status='confirmed' where id=v_booking.id and status='new';
      continue;
    end if;

    v_role:=case when v_tech_count<v_booking.requested_technician_count then 'technician' else 'helper' end;
    if (v_role='technician' and v_tech_offered>0) or (v_role='helper' and v_helper_offered>0) then
      update public.srk_booking_matching_queue set queue_status='searching',
        next_attempt_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()
      where booking_id=v_booking.id;
      continue;
    end if;

    v_offered:=false;
    for v_candidate in
      select c.* from public.srk_find_eligible_workers(v_booking.id,v_role) c
      where not exists(select 1 from public.srk_booking_workers bw
        where bw.booking_id=v_booking.id and bw.worker_id=c.worker_id)
      order by c.distance_km
    loop
      select ws.skill_level_id into v_level from public.srk_worker_skills ws
        where ws.worker_id=v_candidate.worker_id and ws.skill_id=v_booking.selected_skill_id
          and ws.verification_status='approved' limit 1;
      select r.id,case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end
        into v_rate_id,v_rate from public.srk_service_rates r
        where r.category_id=v_booking.category_id and r.skill_level_id=v_level
          and (r.service_type_id is null or r.service_type_id=v_booking.service_type_id)
          and r.rate_status='approved' and r.effective_from<=clock_timestamp()
          and (r.effective_to is null or r.effective_to>clock_timestamp())
          and (case when v_role='technician' then r.technician_hourly_rate else r.helper_hourly_rate end) is not null
        order by (r.service_type_id is not null) desc,r.effective_from desc limit 1;
      if v_rate is null then continue; end if;

      insert into public.srk_booking_workers(booking_id,worker_id,worker_role,assignment_status,
        rate_id,hourly_rate_snapshot,skill_level_snapshot_id,offer_expires_at)
      values(v_booking.id,v_candidate.worker_id,v_role,'offered',v_rate_id,v_rate,v_level,
        case when v_timeout is null then null else clock_timestamp()+make_interval(secs=>v_timeout) end);
      update public.srk_booking_matching_queue set queue_status='searching',attempts=attempts+1,
        last_attempt_at=clock_timestamp(),next_attempt_at=clock_timestamp()+interval '1 minute',
        last_error=null,updated_at=clock_timestamp() where booking_id=v_booking.id;
      v_inserted:=v_inserted+1;
      v_offered:=true;
      exit;
    end loop;

    if not v_offered then
      update public.srk_booking_matching_queue set queue_status='waiting',attempts=attempts+1,
        last_attempt_at=clock_timestamp(),next_attempt_at=clock_timestamp()+interval '1 minute',
        last_error='No eligible online approved worker with an approved rate',updated_at=clock_timestamp()
      where booking_id=v_booking.id;
    end if;
  end loop;
  return v_inserted;
end $$;

create or replace function public.srk_admin_finalize_booking_bill(p_booking_id uuid)
returns public.srk_booking_final_bills
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare
  v_booking public.service_bookings%rowtype; v_bill public.srk_booking_final_bills%rowtype;
  v_labour numeric(12,2):=0; v_material numeric(12,2); v_worker record; v_worker_gross numeric(12,2);
  v_existing public.srk_booking_final_bills%rowtype; v_next_revision integer;
  v_tech_worked integer; v_helper_worked integer;
begin
  if not public.srk_has_admin_permission('bookings.manage') then raise exception 'Booking management permission required'; end if;
  select * into v_booking from public.service_bookings where id=p_booking_id for update;
  if not found then raise exception 'Booking not found'; end if;
  if v_booking.payment_status='paid' then raise exception 'Paid booking cannot be rebilled'; end if;

  select count(*) into v_tech_worked from public.srk_booking_workers bw
  where bw.booking_id=p_booking_id and bw.worker_role='technician'
    and bw.assignment_status in ('completed','released')
    and exists(select 1 from public.srk_worker_work_sessions s where s.booking_worker_id=bw.id and s.billable_seconds>0);
  select count(*) into v_helper_worked from public.srk_booking_workers bw
  where bw.booking_id=p_booking_id and bw.worker_role='helper'
    and bw.assignment_status in ('completed','released')
    and exists(select 1 from public.srk_worker_work_sessions s where s.booking_worker_id=bw.id and s.billable_seconds>0);
  if v_tech_worked<v_booking.requested_technician_count or v_helper_worked<v_booking.requested_helper_count then
    raise exception 'Requested number of Technicians/Helpers has not completed billable work';
  end if;

  if exists(select 1 from public.srk_booking_workers where booking_id=p_booking_id and assignment_status not in ('completed','released','cancelled','rejected')) then
    raise exception 'All assigned workers must complete or be released before final billing';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions s join public.srk_booking_workers bw on bw.id=s.booking_worker_id
    where bw.booking_id=p_booking_id and s.session_status not in ('completed','cancelled')) then
    raise exception 'Every work session must be completed or cancelled before final billing';
  end if;

  for v_worker in
    select bw.id booking_worker_id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot,
      coalesce(sum(s.billable_seconds),0)::bigint seconds
    from public.srk_booking_workers bw left join public.srk_worker_work_sessions s on s.booking_worker_id=bw.id
    where bw.booking_id=p_booking_id and bw.assignment_status in ('completed','released')
    group by bw.id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot
    having coalesce(sum(s.billable_seconds),0)>0
  loop
    if v_worker.hourly_rate_snapshot is null then raise exception 'Worker rate snapshot missing'; end if;
    if v_worker.seconds>coalesce(v_booking.requested_duration_hours,1440)*3600 then
      raise exception 'Worker actual billable time exceeds booked maximum duration';
    end if;
    v_worker_gross:=round((v_worker.seconds::numeric/3600)*v_worker.hourly_rate_snapshot,2);
    v_labour:=v_labour+v_worker_gross;
  end loop;
  v_material:=coalesce(v_booking.materials_amount,0);

  select * into v_existing from public.srk_booking_final_bills where booking_id=p_booking_id for update;
  if found then
    if v_existing.status in ('issued','approved','disputed') then raise exception 'An active final bill already exists'; end if;
    v_next_revision:=v_existing.revision_no+1;
    insert into public.srk_booking_final_bill_revisions(bill_id,revision_no,previous_bill_data,previous_items,reason,archived_by)
    values(v_existing.id,v_existing.revision_no,to_jsonb(v_existing),
      coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at) from public.srk_booking_final_bill_items i where i.bill_id=v_existing.id),'[]'::jsonb),
      'Reissued after work reopening',auth.uid());
    delete from public.srk_booking_final_bill_items where bill_id=v_existing.id;
    update public.srk_booking_final_bills set bill_number='SRK-BILL-'||lpad(nextval('public.srk_bill_number_seq')::text,6,'0'),
      revision_no=v_next_revision,service_amount=v_labour,materials_amount=v_material,discount_amount=0,tax_amount=0,
      status='issued',prepared_at=clock_timestamp(),updated_at=clock_timestamp()
    where id=v_existing.id returning * into v_bill;
  else
    insert into public.srk_booking_final_bills(booking_id,bill_number,revision_no,service_amount,materials_amount,status,prepared_at)
    values(p_booking_id,'SRK-BILL-'||lpad(nextval('public.srk_bill_number_seq')::text,6,'0'),1,
      v_labour,v_material,'issued',clock_timestamp()) returning * into v_bill;
  end if;

  insert into public.srk_booking_final_bill_items(bill_id,item_type,description,quantity,unit,unit_price)
  values(v_bill.id,'labour','Actual worker timer-based labour charges',1,'booking',v_labour);
  if v_material>0 then
    insert into public.srk_booking_final_bill_items(bill_id,item_type,description,quantity,unit,unit_price)
    values(v_bill.id,'material','Materials supplied (separate from commission)',1,'booking',v_material);
  end if;

  for v_worker in
    select bw.id booking_worker_id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot,
      coalesce(sum(s.billable_seconds),0)::bigint seconds
    from public.srk_booking_workers bw left join public.srk_worker_work_sessions s on s.booking_worker_id=bw.id
    where bw.booking_id=p_booking_id and bw.assignment_status in ('completed','released')
    group by bw.id,bw.worker_id,bw.worker_role,bw.hourly_rate_snapshot
    having coalesce(sum(s.billable_seconds),0)>0
  loop
    v_worker_gross:=round((v_worker.seconds::numeric/3600)*v_worker.hourly_rate_snapshot,2);
    insert into public.srk_worker_earnings(booking_id,booking_worker_id,worker_id,worker_role,bill_id,billable_seconds,
      gross_service_earning,company_commission_rate,company_commission,net_earning,payment_method,payout_status,settlement_status)
    values(p_booking_id,v_worker.booking_worker_id,v_worker.worker_id,v_worker.worker_role,v_bill.id,v_worker.seconds,
      v_worker_gross,15.00,round(v_worker_gross*0.15,2),v_worker_gross-round(v_worker_gross*0.15,2),
      case when lower(v_booking.payment_method) in ('upi','card') then 'online' else lower(v_booking.payment_method) end,'pending','pending')
    on conflict(booking_worker_id) do update set bill_id=excluded.bill_id,billable_seconds=excluded.billable_seconds,
      gross_service_earning=excluded.gross_service_earning,company_commission_rate=excluded.company_commission_rate,
      company_commission=excluded.company_commission,net_earning=excluded.net_earning,payment_method=excluded.payment_method,
      payout_status='pending',settlement_status='pending',updated_at=clock_timestamp();
  end loop;
  return v_bill;
end $$;

drop policy if exists srk_worker_read_assigned_bookings on public.service_bookings;
create policy srk_worker_read_assigned_bookings on public.service_bookings
for select to authenticated using(
  public.srk_has_admin_permission('bookings.manage')
  or exists(select 1 from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
    where bw.booking_id=service_bookings.id and w.user_id=auth.uid())
);

drop policy if exists srk_booking_history_participant_read on public.service_booking_status_history;
create policy srk_booking_history_participant_read on public.service_booking_status_history
for select to authenticated using(
  public.srk_has_admin_permission('bookings.manage')
  or exists(select 1 from public.service_bookings b where b.id=service_booking_status_history.booking_id and b.customer_user_id=auth.uid())
  or exists(select 1 from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
    where bw.booking_id=service_booking_status_history.booking_id and w.user_id=auth.uid())
);
